const icons={medical:'<rect x="4" y="6" width="16" height="15" rx="2"/><path d="M9 6V3h6v3M9 13h6m-3-3v6"/>',chat:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-2 2V11.5a9.5 9.5 0 1 1 19 0Z"/><path d="M7 11h.01M12 11h.01M17 11h.01"/>',book:'<path d="M12 5v16M12 5C8 2 4 3 2 4v15c3-1 7-1 10 2 3-3 7-3 10-2V4c-2-1-6-2-10 1Z"/>',home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18M8 15h2m4 0h2"/>',file:'<path d="M14 2H5v20h14V7ZM14 2v5h5M8 12h8m-8 4h6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="m14 5-7 7 7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6Z"/><path d="m8 12 3 3 5-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5ZM20 2v4m-2-2h4"/>',select:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="m7 12 3 3 7-7"/>',send:'<path d="m3 3 19 9-19 9 3-9ZM6 12h16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',refresh:'<path d="M20 11a8 8 0 1 0-2 7M20 4v7h-7"/>',list:'<path d="M9 6h12M9 12h12M9 18h12M3 6h.01M3 12h.01M3 18h.01"/>',chevron:'<path d="m9 5 7 7-7 7"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.chat}</svg>`;
const escapeHtml=(s)=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const doctors=[{name:'张明',dept:'神经内科',title:'主任医师',initial:'张'},{name:'李静',dept:'全科医学科',title:'副主任医师',initial:'李'},{name:'王浩',dept:'心内科',title:'主治医师',initial:'王'}];
const sourceMessages=[
 {id:1,role:'user',time:'10:32',text:'张医生您好，最近三天有些头痛，主要是熬夜之后，两侧太阳穴附近有紧绷感。'},
 {id:2,role:'doctor',time:'10:35',text:'您好，除了头痛，有没有发热、呕吐或视物模糊？最近休息和用药情况怎么样？'},
 {id:3,role:'user',time:'10:36',text:'没有这些情况，也没吃药。最近工作比较忙，每天大概只睡五六个小时。'},
 {id:4,role:'doctor',time:'10:38',text:'先调整作息，保证充足睡眠，减少长时间连续看屏幕，并记录头痛的时间和程度。仅凭目前描述还不能明确原因；如果持续不缓解，建议线下就诊。若突发剧烈头痛，或伴随肢体无力、言语不清，请及时急诊就医。'}
];
const state={page:'patient',selecting:false,selected:new Set(),doctor:0,patient:0,filter:'all',handoff:false,pending:false,handed:new Set(),messages:{0:[],1:[],2:[]},mobileList:false,saved:false,articleTitle:'熬夜后头痛的咨询与就医建议',articleHtml:'',toastTimer:null};
const defaultArticle='<h3>问题描述</h3><p>患者自述近三天出现头痛，主要发生在熬夜后，双侧太阳穴附近有紧绷感。</p><h3>相关背景</h3><p>近期每日睡眠约五至六小时，未使用药物。患者否认发热、呕吐及视物模糊。</p><h3>医生建议</h3><ul><li>调整作息，保证充足睡眠，减少长时间连续看屏幕。</li><li>记录头痛发生的时间和程度；如果持续不缓解，建议线下就诊。</li></ul><h3>适用条件与注意事项</h3><p>仅凭当前描述不能明确头痛原因。本内容为该次咨询的建议，不代表已经确诊。若突发剧烈头痛，或伴随肢体无力、言语不清，应及时急诊就医。</p>';
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
function docName(){return doctors[state.doctor].name}
function isDoctor(){return ['doctor','review','success'].includes(state.page)}
function header(){const doctor=isDoctor();if(doctor)return doctorHeader();return `<header class="site-header"><a href="#patient" class="brand" aria-label="智慧医疗在线咨询"><span class="brand-symbol">${icon('medical')}</span><span class="brand-name">智慧医疗<small>HEALTHCARE · AI</small></span></a><nav class="site-nav" aria-label="产品导航">${doctor?`<span>${icon('home')}工作台</span><a href="#doctor" class="active">${icon('chat')}患者咨询</a><span>${icon('calendar')}就诊安排</span><span>${icon('file')}患者档案</span>`:`<span>${icon('home')}首页</span><a href="#ai" class="${state.page==='ai'?'active':''}">${icon('spark')}AI 问诊</a><a href="#patient" class="${state.page==='patient'?'active':''}">${icon('chat')}在线咨询</a><span>${icon('calendar')}预约挂号</span><span>${icon('file')}健康档案</span><span>${icon('book')}健康资讯</span>`}</nav><div class="account"><span class="avatar small ${doctor?'':'patient'}">${doctor?'张':'林'}</span><span>${doctor?'张明医生':'林晓'}<small class="account-role">${doctor?'医生工作台':'个人账户'}</small></span></div></header>`}
function navigation(){document.querySelector('#prototype-nav').innerHTML=[['ai','AI 转人工'],['patient','患者聊天'],['doctor','医生聊天'],['review','知识确认']].map(([id,label])=>`<a href="#${id}" class="${state.page===id||(state.page==='success'&&id==='review')?'active':''}" ${state.page===id?'aria-current="page"':''}>${label}</a>`).join('')}
function conversationList(mode){const doctor=mode==='doctor',ai=mode==='ai';const names=doctor?['林晓','陈悦','周先生']:doctors.map(d=>d.name);return `<aside class="panel conversation-list"><div class="list-head"><div class="list-title"><h2>${ai?'问诊历史':doctor?'患者会话':'我的咨询'}</h2><span class="count">${ai?'2':'3'}</span></div><label class="search">${icon('search')}<input id="conversation-search" aria-label="${ai?'搜索问诊历史':doctor?'搜索患者':'搜索医生或科室'}" placeholder="${ai?'搜索问诊历史':doctor?'搜索患者姓名':'搜索医生或科室'}"></label></div>${!ai?`<div class="filter-tabs"><button class="${state.filter==='all'?'active':''}" data-filter="all">全部咨询</button><button class="${state.filter==='pending'?'active':''}" data-filter="pending">${doctor?'待回复 2':'未读消息 1'}</button></div>`:''}<div class="conversation-items">${ai?`<button class="conversation active" data-ai-history="current"><div class="conversation-copy"><div class="conversation-top"><strong>最近熬夜后头痛</strong></div><div class="conversation-sub">今天 · 10:20</div><div class="conversation-last"><span>了解头痛与日常作息的关系</span></div></div></button><button class="conversation" data-ai-history="old"><div class="conversation-copy"><div class="conversation-top"><strong>日常饮食与健康管理</strong></div><div class="conversation-sub">10 月 18 日</div></div></button>`:names.map((name,i)=>`<button class="conversation ${(doctor?state.patient:state.doctor)===i?'active':''}" data-conversation="${i}" data-search="${name} ${doctor?'':doctors[i].dept}" ${state.filter==='pending'&&(doctor?i===2:i!==0)?'hidden':''}><span class="avatar ${doctor?'patient':i===1?'blue':i===2?'gold':''}">${doctor?name[0]:doctors[i].initial}</span><div class="conversation-copy"><div class="conversation-top"><strong>${doctor?name:name+'医生'}</strong><time>${i===0?'10:38':i===1?'昨天':'10/18'}</time></div><div class="conversation-sub">${doctor?['女 · 28 岁','女 · 36 岁','男 · 52 岁'][i]:`${doctors[i].dept} · ${doctors[i].title}`}</div><div class="conversation-last"><span>${doctor?['最近三天有些头痛…','最近胃部有些不适，想咨询一下','好的，谢谢医生。'][i]:['先调整作息，保证充足睡眠…','好的，有变化随时联系。','谢谢医生，我会继续记录。'][i]}</span>${i===(doctor?1:0)?'<span class="badge">1</span>':''}</div></div></button>`).join('')}<p class="empty-filter" hidden>没有找到匹配的会话</p></div><div class="list-note">${icon('shield')}聊天记录保留，随时继续沟通</div></aside>`}
function messageMarkup(m,doctor=false){const mine=doctor?m.role==='doctor':m.role==='user';const name=m.role==='doctor'?'张明医生':'林晓';return `<div class="message ${mine?'mine':''} ${state.selected.has(m.id)?'selected':''}" data-message-id="${m.id}"><label class="select-message"><input type="checkbox" aria-label="选择${name} ${m.time}的消息" data-select="${m.id}" ${state.selected.has(m.id)?'checked':''}></label><span class="avatar ${m.role==='user'?'patient':''}">${m.role==='doctor'?'张':'林'}</span><div class="message-body"><div class="message-meta"><span>${name}</span><time>${m.time}</time></div><div class="bubble">${escapeHtml(m.text)}</div>${mine&&!state.selecting?'<span class="read-status">已读</span>':''}</div></div>`}
function summaryCard(){return `<div class="message summary"><span class="avatar ai">${icon('spark')}</span><div class="message-body"><div class="message-meta"><span>由患者转入</span><time>刚刚</time></div><div class="summary-card"><div class="summary-top">${icon('file')}AI 问诊摘要<time>今天 · 最近熬夜后头痛</time></div><dl><dt>患者自述</dt><dd>头痛持续三天，熬夜后明显，双侧太阳穴有紧绷感。近期睡眠约五至六小时，无发热、呕吐。</dd><dt>AI 已给出的建议</dt><dd>记录症状变化，调整作息；持续不缓解时到医院进一步评估。</dd><dt>需要医生了解</dt><dd>头痛的具体程度、既往病史及是否存在其他伴随症状。</dd></dl><div class="summary-foot">由 AI 根据本次问诊整理，供医生了解背景，不代表医生诊断。</div></div></div></div>`}
function composer(){return `<div class="composer"><div class="compose-box"><textarea id="message-input" aria-label="聊天消息" placeholder="${isDoctor()?'请输入回复，继续为患者解答…':'描述您的情况，也可以继续追问…'}"></textarea><div class="compose-bottom"><span class="compose-hint">${icon('shield')} 仅您与${isDoctor()?'患者':'医生'}可见 <span class="desktop-only"> · Enter 发送</span></span><button class="btn primary" id="send">发送 ${icon('send')}</button></div></div><p class="composer-note">线上咨询不替代线下诊疗；如遇紧急情况，请及时就医。</p></div>`}
function infoColumn(){return `<aside class="info-column"><section class="info-block"><h3>${icon('user')}患者信息</h3><dl><dt>姓名</dt><dd>林晓</dd><dt>性别 / 年龄</dt><dd>女 / 28 岁</dd><dt>首次咨询</dt><dd>2026 年 10 月 18 日</dd><dt>本次主诉</dt><dd>熬夜后头痛</dd></dl><p class="note">信息来自本次咨询，供沟通参考。</p></section><section class="info-block selection-guide"><h3>${icon('book')}让经验帮助更多人</h3><p>把有参考价值的解答，整理成知识库文章。</p><div class="step-item"><span>1</span><div><strong>选择相关对话</strong><p>同时选择问题和回复，保留上下文。</p></div></div><div class="step-item"><span>2</span><div><strong>检查整理后的文章</strong><p>像编辑普通文章一样修改内容。</p></div></div><div class="step-item"><span>3</span><div><strong>确认存入知识库</strong><p>处理完成后，供 AI 问诊参考。</p></div></div><button class="btn" id="history-draft">${icon('file')}知识整理记录${state.saved?' · 1':''}</button></section></aside>`}
function selectionBar(){return `<div class="selection-bar"><div><strong>已选择 <span id="selected-count">${state.selected.size}</span> 条消息</strong><p>仅整理选中的内容，原聊天记录保持不变</p></div><div class="actions"><button class="btn" id="cancel-selection">取消选择</button><button class="btn primary" id="generate" ${!state.selected.size?'disabled':''}>${icon('book')}存入知识库</button></div></div>`}
function chatPage(doctor){const d=doctors[state.doctor];const other=doctor?state.patient>0:state.doctor>0;const person=doctor?['林晓','陈悦','周先生'][state.patient]:d.name+'医生';return `${header()}<main class="shell" id="main"><div class="page-heading"><div><h1>${doctor?'患者咨询':'在线咨询'}</h1><p>${doctor?'持续关注患者的每一次反馈，让专业解答成为可复用的知识。':'与熟悉您的医生继续聊，让每一次沟通都有延续。'}</p></div><div class="heading-side"><span class="quiet-label">${icon('shield')}历史记录长期保留</span>${!doctor?`<button class="btn primary" id="choose-doctor">${icon('plus')}选择医生</button>`:`<span class="tag warm">2 位患者待回复</span><button class="btn" id="history-draft">${icon('file')}知识整理记录</button>`}</div></div><div class="workspace ${doctor?'doctor-workspace':''} ${state.mobileList?'show-list':''}">${conversationList(doctor?'doctor':'patient')}<section class="panel chat ${state.selecting?'selecting':''}"><div class="chat-head"><button class="icon-btn mobile-back" id="show-list" aria-label="返回会话列表">${icon('back')}</button><span class="avatar ${doctor?'patient':''}">${person[0]}</span><div class="chat-title"><h2>${person}<span class="tag">${doctor?'持续咨询':'长期聊天'}</span></h2><p>${doctor?['女 · 28 岁','女 · 36 岁','男 · 52 岁'][state.patient]:`${d.dept} · ${d.title}`}</p></div><div class="head-actions">${doctor?`<button class="btn" id="toggle-patient-info" aria-expanded="false" aria-controls="patient-info">${icon('user')}患者信息</button><button class="btn ${state.selecting?'soft':''}" id="toggle-selection">${icon('select')}${state.selecting?'退出选择':'选择内容'}</button>`:`<span class="tag desktop-only">${icon('clock')}医生将尽快回复</span>`}</div></div>${doctor?'<div class="context-strip"><span>本次关注 <strong>熬夜后头痛</strong></span><span>上次联系 <strong>10 月 18 日</strong></span></div>':''}${state.selecting?'<div class="selection-intro">勾选有参考价值的消息，可同时选择患者提问和医生回复。</div>':''}<div class="messages" id="messages"><div class="date-divider">今天 · 10 月 22 日</div>${state.pending?'<div class="pending-inline" role="status"><span class="spinner"></span>正在整理问诊摘要，完成后将自动发送…</div>':''}${other?`<div class="date-divider">您与${person}的聊天记录将保留在这里</div><div class="message"><span class="avatar">${person[0]}</span><div class="message-body"><div class="message-meta">${person} · 昨天</div><div class="bubble">${doctor?'您好医生，想咨询一下最近的身体情况。':'您好，有什么需要了解的情况，可以在这里继续告诉我。'}</div></div></div>`:sourceMessages.map(m=>messageMarkup(m,doctor)).join('')}${(doctor?state.patient===0&&state.handed.has(0):state.handed.has(state.doctor))?summaryCard():''}${(state.messages[doctor?state.patient:state.doctor]||[]).map(m=>messageMarkup(m,doctor)).join('')}</div>${state.selecting?selectionBar():composer()}</section>${doctor?doctorPatientInfo():''}</div><p class="scenario-note">原型演示 · 所有人物、聊天及处理结果均为虚构</p></main>`}
function aiPage(){return `${header()}<main class="shell" id="main"><div class="page-heading"><div><h1>AI 问诊</h1><p>先了解自己的身体状况，也可以随时向医生寻求帮助。</p></div><span class="quiet-label desktop-only">${icon('shield')}您的健康信息受到保护</span></div><div class="workspace">${conversationList('ai')}<section class="panel chat ai-chat"><div class="chat-head"><span class="avatar ai">${icon('spark')}</span><div class="chat-title"><h2>AI 健康助手</h2><p>当前对话：最近熬夜后头痛</p></div><span class="tag">智能问诊</span></div><div class="messages"><div class="date-divider">今天 · 10:20</div><div class="message mine"><span class="avatar patient">林</span><div class="message-body"><div class="message-meta">我 · 10:20</div><div class="bubble">最近三天总是头痛，主要是熬夜后太阳穴附近有紧绷感。没有发热和呕吐，每天睡五六个小时。</div></div></div><div class="message"><span class="avatar ai">${icon('spark')}</span><div class="message-body"><div class="message-meta">AI 健康助手 · 10:21</div><div class="bubble ai-content"><p>了解了，您提到头痛与近期熬夜有关。睡眠不足可能是影响因素之一，但<strong>仅凭这些描述还不能确定头痛原因</strong>。</p><p>您可以先关注下面几个方面：</p><ul><li>尽量规律作息，保证充足睡眠，避免持续熬夜。</li><li>记录头痛出现的时间、持续多久，以及疼痛程度。</li><li>如果头痛持续或加重，建议及时就诊，由医生进一步评估。</li></ul><p>如果出现突发剧烈头痛、肢体无力或言语不清，请及时急诊就医。</p><span class="reference">${icon('book')}参考：头痛的日常观察与就医提示</span></div></div></div><div class="handoff-card"><span class="handoff-icon">${icon('medical')}</span><div><h3>想让医生进一步了解您的情况？</h3><p>选择医生后，本次问诊摘要将自动发送，免去重复描述。</p></div><button class="btn primary" id="handoff">转人工咨询 ${icon('arrow')}</button></div></div><div class="composer"><div class="compose-box"><textarea aria-label="AI 问诊消息" id="ai-input" placeholder="继续补充您的症状或健康问题…"></textarea><div class="compose-bottom"><span class="compose-hint">AI 建议仅供健康参考，不能替代医生诊断</span><button class="btn primary" id="ai-send">发送 ${icon('send')}</button></div></div></div></section></div><p class="scenario-note">原型演示 · AI 回答为预设示例</p></main>`}
function selectedSources(){return [...sourceMessages,...state.messages[0]].filter(m=>state.selected.has(m.id))}
function articleForSelection(){const selected=selectedSources();if(selected.length===4&&selected.every(m=>m.id<=4))return defaultArticle;return `<h3>问题描述与背景</h3>${selected.filter(m=>m.role==='user').map(m=>`<p>${escapeHtml(m.text.replace('张医生您好，',''))}</p>`).join('')||'<p>所选消息未包含患者背景，请根据已核实的信息补充。</p>'}<h3>医生解答</h3>${selected.filter(m=>m.role==='doctor').map(m=>`<p>${escapeHtml(m.text.replace('您好，',''))}</p>`).join('')||'<p>所选内容中没有医生解答，请补充或核实后入库。</p>'}<h3>适用条件与注意事项</h3><p>本内容来自一次咨询，仅适用于文中所述背景，不代表已经明确诊断。请核实建议的适用范围后存入知识库。</p>`}
function reviewPage(){if(!state.selected.size)sourceMessages.forEach(m=>state.selected.add(m.id));if(!state.articleHtml)state.articleHtml=articleForSelection();return `${header()}<main class="shell review-page" id="main"><div class="page-heading editor-heading"><div><div class="backline"><a href="#doctor">患者咨询</a>${icon('chevron')}<span>林晓的咨询</span>${icon('chevron')}<span>整理知识</span></div><h1>确认知识内容</h1><p>已根据您选择的对话整理，请检查内容是否准确。</p></div><div class="heading-side"><button class="btn" id="back-chat">${icon('back')}返回聊天</button></div></div><button class="btn mobile-only source-toggle" id="toggle-sources" aria-expanded="false">${icon('chat')}查看选中的 ${state.selected.size} 条对话</button><div class="review-layout"><aside class="source-pane"><h2>本次选中的对话</h2><p>${state.selected.size} 条消息 · 今天 10:32—10:38</p>${selectedSources().map(m=>`<div class="source-item"><div class="source-role">${icon(m.role==='doctor'?'medical':'user')} ${m.role==='doctor'?'张明医生':'患者'} <time>${m.time}</time></div><p>${escapeHtml(m.text)}</p></div>`).join('')}<div class="source-help">${icon('shield')}来源仅用于核对，不会公开患者身份。</div></aside><section class="article-panel"><div class="review-notice">${icon('shield')}请核对医学表述，并确认文章中不含患者姓名、电话等个人信息。</div><div class="editor-toolbar" role="toolbar" aria-label="文章排版"><button data-format="formatBlock" data-value="p" aria-label="设为正文">正文</button><button data-format="formatBlock" data-value="h3" aria-label="设为小标题">小标题</button><span class="toolbar-sep"></span><button data-format="bold" aria-label="加粗"><strong>B</strong></button><button data-format="insertUnorderedList" aria-label="项目列表">${icon('list')}</button><span class="save-label" id="save-label">${icon('check')}草稿已保存至本次演示</span></div><article class="article"><label for="article-title">文章标题</label><input class="article-title" id="article-title" value="${escapeHtml(state.articleTitle)}"><div class="article-meta">咨询知识 · 神经内科 <span style="margin-left:18px">整理医生：张明</span></div><div class="article-body" contenteditable="true" role="textbox" aria-label="知识文章正文" aria-multiline="true" id="article-body">${state.articleHtml}</div></article><footer class="article-footer"><p>确认后，这篇文章将存入知识库，供 AI 问诊参考。</p><div class="actions"><button class="btn" id="regenerate">${icon('refresh')}重新整理</button><button class="btn primary" id="confirm-knowledge">${icon('book')}确认存入知识库</button></div></footer></section></div><p class="scenario-note">原型演示 · 内容可编辑，草稿仅在当前页面会话中保留</p></main>`}
function successPage(){return `${header()}<main class="shell" id="main"><div class="page-heading"><div><h1>知识整理记录</h1><p>把一次专业解答，变成可以持续参考的知识。</p></div></div><section class="success-content"><div class="success-mark">${icon('check')}</div><h2>已存入知识库</h2><p>文章已处理完成，可供 AI 问诊参考。</p><div class="saved-file"><span class="avatar">${icon('file')}</span><div><strong>${escapeHtml(state.articleTitle)}</strong><small>神经内科 · 整理医生：张明 · 来源：${state.selected.size} 条咨询消息</small></div></div><div class="actions"><button class="btn" id="view-article">${icon('file')}查看文章</button><a class="btn primary" href="#doctor">返回患者咨询 ${icon('arrow')}</a></div><div class="completion-detail"><span>${icon('check')}文章已保存</span><span>${icon('check')}已可供 AI 参考</span></div></section><p class="scenario-note">原型演示 · 本次操作未写入真实知识库</p></main>`}
function render(){if(state.page!=='doctor')state.selecting=false;document.body.classList.toggle('doctor-view',isDoctor());navigation();document.querySelector('#app').innerHTML=state.page==='ai'?aiPage():state.page==='review'?reviewPage():state.page==='success'?successPage():chatPage(state.page==='doctor');bind();bindDoctorShell();const messages=document.querySelector('.messages');if(messages&&!state.selecting)messages.scrollTop=messages.scrollHeight;}
function navigate(page){if(location.hash==='#'+page){state.page=page;render()}else location.hash=page}
function saveDraft(){const title=document.querySelector('#article-title'),body=document.querySelector('#article-body');if(title)state.articleTitle=title.value;if(body)state.articleHtml=body.innerHTML;const label=document.querySelector('#save-label');if(label)label.innerHTML=icon('check')+'草稿已保存至本次演示'}
let dialogReturnFocus;
function chooseDoctor(handoff=false){state.handoff=handoff;dialogReturnFocus=document.activeElement;const dialog=document.querySelector('#doctor-dialog');dialog.innerHTML=`<div class="dialog-content"><div class="dialog-header"><h2 id="doctor-dialog-title">${handoff?'选择咨询医生':'与医生继续沟通'}</h2><button class="icon-btn" id="close-dialog" aria-label="关闭医生选择">${icon('close')}</button></div><p>${handoff?'选定医生后，本次 AI 问诊摘要会自动发送到聊天中。':'选择一位医生，进入您与医生之间的长期聊天。'}</p><label for="doctor-select">咨询医生</label><select id="doctor-select"><option value="">请选择医生</option>${doctors.map((d,i)=>`<option value="${i}">${d.name} · ${d.dept} · ${d.title}</option>`).join('')}</select><div class="dialog-note">${icon('shield')}<span>${handoff?'无需重复描述病情。已有聊天会直接继续，历史记录完整保留。':'同一位医生始终对应同一段聊天，您可以随时查看历史、继续追问。'}</span></div></div><div class="dialog-footer"><button class="btn" id="cancel-dialog">取消</button></div>`;dialog.showModal();dialog.querySelector('#close-dialog').onclick=()=>dialog.close();dialog.querySelector('#cancel-dialog').onclick=()=>dialog.close();dialog.querySelector('#doctor-select').onchange=e=>{if(e.target.value==='')return;state.doctor=Number(e.target.value);dialog.close();state.mobileList=false;state.page='patient';if(handoff&&!state.handed.has(state.doctor)){const doctor=state.doctor;state.pending=true;navigate('patient');render();setTimeout(()=>{state.handed.add(doctor);state.pending=false;if(state.page==='patient')render();toast('本次问诊摘要已自动发送给'+doctors[doctor].name+'医生')},1100)}else{navigate('patient');if(handoff)toast('本次问诊摘要已发送，已为您打开原聊天')}};dialog.onclose=()=>dialogReturnFocus?.isConnected&&dialogReturnFocus.focus();}
function bind(){const on=(id,event,handler)=>{const el=document.getElementById(id);if(el)el.addEventListener(event,handler)};
 on('choose-doctor','click',()=>chooseDoctor());on('handoff','click',()=>{state.page='patient';navigate('patient');render();chooseDoctor(true)});
 on('toggle-selection','click',()=>{state.selecting=!state.selecting;if(!state.selecting)state.selected.clear();render()});
 on('cancel-selection','click',()=>{state.selecting=false;state.selected.clear();render()});
 document.querySelectorAll('[data-select]').forEach(el=>el.onchange=()=>{const id=Number(el.dataset.select);el.checked?state.selected.add(id):state.selected.delete(id);el.closest('.message').classList.toggle('selected',el.checked);document.querySelector('#selected-count').textContent=state.selected.size;document.querySelector('#generate').disabled=!state.selected.size});
 on('generate','click',()=>{const button=document.querySelector('#generate');button.disabled=true;button.innerHTML='<span class="spinner"></span>正在整理…';setTimeout(()=>{state.articleHtml=articleForSelection();state.saved=false;navigate('review')},850)});
 on('send','click',sendMessage);on('message-input','keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();sendMessage()}});
 on('show-list','click',()=>{state.mobileList=true;render()});
 document.querySelectorAll('[data-conversation]').forEach(el=>el.onclick=()=>{state.selecting=false;state.mobileList=false;if(isDoctor())state.patient=Number(el.dataset.conversation);else state.doctor=Number(el.dataset.conversation);render()});
 document.querySelectorAll('[data-filter]').forEach(el=>el.onclick=()=>{state.filter=el.dataset.filter;render()});
 on('conversation-search','input',e=>{let n=0;document.querySelectorAll('[data-search]').forEach(el=>{const hide=!el.dataset.search.includes(e.target.value.trim())||(state.filter==='pending'&&(isDoctor()?el.dataset.conversation==='2':el.dataset.conversation!=='0'));el.hidden=hide;if(!hide)n++});document.querySelector('.empty-filter').hidden=n!==0});
 document.querySelectorAll('[data-ai-history]').forEach(el=>el.onclick=()=>toast(el.dataset.aiHistory==='current'?'已是当前问诊':'此原型聚焦“头痛问诊转人工”流程'));
 on('ai-send','click',()=>{const input=document.querySelector('#ai-input');if(input.value.trim()){toast('原型未连接大模型，请体验下方“转人工咨询”');}else input.focus()});
 on('toggle-sources','click',()=>{const pane=document.querySelector('.source-pane');pane.classList.toggle('mobile-expanded');document.querySelector('#toggle-sources').setAttribute('aria-expanded',pane.classList.contains('mobile-expanded'));});
 on('back-chat','click',()=>{saveDraft();state.selecting=false;navigate('doctor')});
 on('article-title','input',saveDraft);on('article-body','input',saveDraft);
 document.querySelectorAll('[data-format]').forEach(el=>{el.onmousedown=e=>e.preventDefault();el.onclick=()=>{document.querySelector('#article-body').focus();document.execCommand(el.dataset.format,false,el.dataset.value||null);saveDraft()}});
 on('regenerate','click',()=>{if(!confirm('重新整理将覆盖当前文章的修改，是否继续？'))return;const btn=document.querySelector('#regenerate');btn.disabled=true;btn.innerHTML='<span class="spinner"></span>正在整理';setTimeout(()=>{state.articleHtml=articleForSelection();render();toast('已根据选中的对话重新整理')},700)});
 on('confirm-knowledge','click',()=>{saveDraft();if(!state.articleTitle.trim()||!document.querySelector('#article-body').textContent.trim()){toast('请补充文章标题和正文');return}const btn=document.querySelector('#confirm-knowledge');btn.disabled=true;btn.innerHTML='<span class="spinner"></span>正在存入知识库';setTimeout(()=>{state.saved=true;state.selecting=false;navigate('success')},1000)});
 on('history-draft','click',()=>{if(state.saved)navigate('success');else if(state.articleHtml)navigate('review');else toast('暂无整理记录，先点击“选择内容”勾选相关消息')});
 on('view-article','click',()=>{navigate('review');toast('原型展示已存文章内容，编辑操作仅供演示')});
}
function sendMessage(){const input=document.querySelector('#message-input');if(!input?.value.trim()){input?.focus();return}const text=input.value.trim(),key=isDoctor()?state.patient:state.doctor;state.messages[key].push({id:100+state.messages[key].length,role:isDoctor()?'doctor':'user',time:'刚刚',text});render();const messages=document.querySelector('#messages');messages.scrollTop=messages.scrollHeight;toast('消息已发送（演示）')}
document.querySelector('#reset').onclick=()=>{state.selected.clear();state.messages={0:[],1:[],2:[]};state.handed.clear();state.selecting=false;state.articleHtml='';state.articleTitle='熬夜后头痛的咨询与就医建议';state.saved=false;state.doctor=0;state.patient=0;state.filter='all';state.mobileList=false;navigate('patient');render();toast('演示已重置')};
window.addEventListener('hashchange',()=>{if(state.page==='review')saveDraft();const page=location.hash.slice(1);state.page=['ai','patient','doctor','review','success'].includes(page)?page:'patient';state.filter='all';state.mobileList=false;if(state.page!=='doctor')state.selecting=false;render();window.scrollTo(0,0)});
state.page=['ai','patient','doctor','review','success'].includes(location.hash.slice(1))?location.hash.slice(1):'patient';render();
